import type { TestStatus } from "@playwright/test";
import type { TestError, TestStep } from "@playwright/test/reporter";
import { Stage, Status, type StatusDetails, type StepResult } from "allure-js-commons";
import { getMessageAndTraceFromError, stripAnsi } from "allure-js-commons/sdk";

import { ALLURE_STEP_STATUS_ANNOTATION, isAllureStepStatus } from "./syncAnnotations.js";

export const AFTER_HOOKS_ROOT_STEP_TITLE = "After Hooks";

export const BEFORE_HOOKS_ROOT_STEP_TITLE = "Before Hooks";

export const getStatusDetails = (error: TestError): StatusDetails => {
  const details = getMessageAndTraceFromError(error);

  if (error.snippet) {
    details.trace = [stripAnsi(error.snippet), details.trace].filter(Boolean).join("\n\n");
  }

  return details;
};

export const statusToAllureStats = (status: TestStatus, expectedStatus: TestStatus): Status => {
  if (status === "skipped") {
    return Status.SKIPPED;
  }

  if (status === "timedOut") {
    return Status.BROKEN;
  }

  if (status === expectedStatus) {
    return Status.PASSED;
  }

  return Status.FAILED;
};

export const isDescendantOfStepWithTitle = (step: TestStep, title: string): boolean => {
  let parent = step.parent;

  while (parent) {
    if (parent.title === title) {
      return true;
    }

    parent = parent.parent;
  }

  return false;
};

export const isAfterHookStep = (step: TestStep) => isDescendantOfStepWithTitle(step, AFTER_HOOKS_ROOT_STEP_TITLE);

export const isBeforeHookStep = (step: TestStep) => isDescendantOfStepWithTitle(step, BEFORE_HOOKS_ROOT_STEP_TITLE);

export const diffEndRegexp = /-((expected)|(diff)|(actual))\.(png|webp)$/;

export const normalizeHookTitle = (title: string) => {
  return title.replace(/^[aA]ttach\s"(.+)"$/, "$1");
};

export const normalizeAttachStepTitle = (title: string): string => {
  const match = title.match(/["'`]{1}(.+?)["'`]{1}/);
  if (match?.[1]) {
    return match[1];
  }
  return title.replace(/^(test\.)?attach\s*/i, "").trim();
};

export const getSkipAnnotation = (step: Pick<TestStep, "annotations">) => {
  return step.annotations.find((annotation) => annotation.type === "skip");
};

// Playwright implements the test.skip() and test.fixme() modifiers by throwing an internal error with
// this message. When a modifier is called from a hook or from inside a step, the error is attached to
// the surrounding step, so a skipped test reaches the reporter with errored steps although nothing failed.
const SKIP_MODIFIER_ERROR_REGEXP = /^(?:\S*Error:\s)?Test is skipped:\s?([\s\S]*)$/;

/**
 * Detects an error produced by a Playwright skip modifier and extracts the reason passed to it.
 * Returns `undefined` for any other error, including a genuine failure.
 */
export const getSkipModifierError = (error: Pick<TestError, "message">): { reason?: string } | undefined => {
  const match = error.message ? SKIP_MODIFIER_ERROR_REGEXP.exec(error.message) : null;

  if (!match) {
    return undefined;
  }

  const reason = match[1].trim();

  return reason ? { reason } : {};
};

export const getStepStatusData = (
  step: Pick<TestStep, "annotations" | "error">,
): {
  status: Status;
  statusDetails?: StatusDetails;
} => {
  const annotatedStatus = step.annotations.find(
    (annotation) => annotation.type === ALLURE_STEP_STATUS_ANNOTATION && isAllureStepStatus(annotation.description),
  )?.description;

  if (annotatedStatus !== undefined) {
    return {
      status: annotatedStatus as Status,
      statusDetails: step.error ? { ...getStatusDetails(step.error) } : undefined,
    };
  }

  if (step.error) {
    const skipModifierError = getSkipModifierError(step.error);

    if (skipModifierError) {
      return {
        status: Status.SKIPPED,
        statusDetails: skipModifierError.reason ? { message: skipModifierError.reason } : undefined,
      };
    }

    return {
      status: Status.FAILED,
      statusDetails: { ...getStatusDetails(step.error) },
    };
  }

  const skipAnnotation = getSkipAnnotation(step);

  if (skipAnnotation) {
    return {
      status: Status.SKIPPED,
      statusDetails: skipAnnotation.description ? { message: skipAnnotation.description } : undefined,
    };
  }

  return {
    status: Status.PASSED,
  };
};

export const finalizeStepResult = (stepResult: StepResult, step: Pick<TestStep, "annotations" | "error">) => {
  const { status: nextStatus, statusDetails } = getStepStatusData(step);

  stepResult.status = nextStatus;
  stepResult.stage = Stage.FINISHED;

  if (statusDetails) {
    // Preserve any previously collected fields and only overwrite values provided by the current step outcome.
    stepResult.statusDetails = { ...stepResult.statusDetails, ...statusDetails };
  }
};
